mapper.select:
select odpr.order_record_id as billDetailId, date_format(br.crt_time, '%Y-%m-%d') as billDate, br.bill_number as billNum, odpr.patient_id as patientId, od.type as itemType, btd.itemCategoryId, btd.itemCategoryName, od.billing_item_id as itemId, btd.itemName, od.quantity as quantity, odpr.actual_receivable as itemActualAmount, br.actual_receivable_amount as billActualAmount, odpr.coupon_workload as itemSupplyWorkloadAmount from order_detail_pay_record odpr inner join order_detail od on odpr.order_detail_id = od.id left join ( select bt.id as itemId, bt.name as itemName, 0 as itemType, btc.id as itemCategoryId, btc.name as itemCategoryName from base_tariff bt left join base_tariff_category btc on bt.tariff_category_id = btc.id union all select bot.id as itemId, bot.name as itemName, 1 as itemType, botc.id as itemCategoryId, botc.name as itemCategoryName from base_oral_tariff bot left join base_oral_tariff_category botc on bot.oral_tariff_category_id = botc.id ) btd on od.type = btd.itemType and od.billing_item_id = btd.itemId inner join bill_record br on odpr.bill_record_id = br.id
date_format(odpr.crt_time, '%Y-%m') = #{query.currentMonth}
and odpr.org_id = #{query.orgId} and br.org_id = #{query.orgId} and od.org_id = #{query.orgId}
order by br.crt_time desc
